import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

test('compiled CLI separates a JSON sum from an invalid operand error', () => {
  const entry = fileURLToPath(new URL('../dist/cli.js', import.meta.url));
  const options = { encoding: 'utf8', input: '' } as const;

  const invalid = spawnSync(process.execPath, [entry, 'sum', '7', 'bad', '-2', '0.5', '--json'], options);
  assert.ifError(invalid.error);
  assert.equal(invalid.status, 2);
  assert.equal(invalid.stdout, '');
  assert.match(invalid.stderr, /Invalid number/);

  const valid = spawnSync(process.execPath, [entry, 'sum', '7', '-2', '0.5', '--json'], options);
  assert.ifError(valid.error);
  assert.equal(valid.status, 0);
  assert.equal(valid.stderr, '');
  assert.deepEqual(JSON.parse(valid.stdout), { total: 5.5 });
});
